var minCost = function(grid) {
    const m = grid.length;
    const n = grid[0].length;

    // dp[i][j] stores reachable XOR states up to 1023
    const dp = Array.from({ length: m }, () =>
        Array.from({ length: n }, () => new Uint8Array(1024))
    );

    dp[0][0][grid[0][0]] = 1;

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (i === 0 && j === 0) continue;
            const val = grid[i][j];
            for (let x = 0; x < 1024; x++) {
                let reachable = false;
                if (i > 0 && dp[i - 1][j][x]) reachable = true;
                if (j > 0 && dp[i][j - 1][x]) reachable = true;
                if (reachable) {
                    dp[i][j][x ^ val] = 1;
                }
            }
        }
    }

    for (let x = 0; x < 1024; x++) {
        if (dp[m - 1][n - 1][x]) {
            return x;
        }
    }

    return -1;
};
